value.customCss:
@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@300;400;600&display=swap');

.xt-root {
  /* 暗紫微光配色 */
  --xt-bg: #080508; 
  --xt-text: #d1c2d1; 
  --xt-text-sub: #8f7a8f; 
  --xt-text-muted: #524052;
  --xt-accent: #855c85; /* 褪色紫罗兰 */
  --xt-accent-bg: rgba(133, 92, 133, 0.15); 
  --xt-border: #1f141f;
  --xt-font: 'Noto Serif SC', serif;

  background: linear-gradient(135deg, #050205 0%, #0d080d 100%);
  border: 1px solid var(--xt-border); box-shadow: 0 15px 40px rgba(0,0,0,0.9);
  position: relative; max-height: 75vh; overflow-y: auto; overflow-x: hidden; padding: 15px 10px 5px 15px; 
}

.xt-root::after { content: ""; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)' opacity='0.04'/%3E%3C/svg%3E"); pointer-events: none; z-index: 99; }
.xt-root::-webkit-scrollbar { width: 3px; } .xt-root::-webkit-scrollbar-track { background: transparent; } .xt-root::-webkit-scrollbar-thumb { background: var(--xt-border); } .xt-root::-webkit-scrollbar-thumb:hover { background: var(--xt-accent); }

.xt-name { color: #e6dce6; letter-spacing: 2px; font-size: 15px; } .xt-header { margin-top: -5px; margin-bottom: 5px; } 
.xt-grid-stat { border: none; border-left: 2px solid var(--xt-accent-bg); border-radius: 0; padding: 5px; } .xt-grid-stat-value { color: var(--xt-accent); font-style: italic; } .xt-ring-fill { stroke: var(--xt-accent); }
.xt-section-title { font-size: 11px; letter-spacing: 2px; color: var(--xt-accent); border-bottom: 1px solid var(--xt-border); padding-bottom: 4px; margin-bottom: 8px; } .xt-section-title::before { content: "✦ "; }
.xt-text-timestamp { font-family: monospace; font-size: 10px; color: var(--xt-text-muted); letter-spacing: 2px; margin-bottom: 5px; } .xt-divider { border: none; height: 1px; margin: 20px 0; background: linear-gradient(90deg, transparent, var(--xt-accent-bg), transparent); }

.xt-quote { background: transparent; font-size: 13px; line-height: 2.2; color: var(--xt-text); text-align: center; padding: 15px 0; margin: 5px 0 20px 0; border-top: 1px solid rgba(133, 92, 133, 0.4); border-bottom: 1px solid rgba(133, 92, 133, 0.4); box-shadow: inset 0 10px 20px -10px rgba(133, 92, 133, 0.08), inset 0 -10px 20px -10px rgba(133, 92, 133, 0.08); letter-spacing: 1px; } .xt-quote::before, .xt-quote::after { display: none; }
.xt-text-theLie, .xt-text-impulse { font-size: 11px; color: var(--xt-text-sub); background: rgba(133, 92, 133, 0.05); padding: 6px 10px; border-left: 2px solid var(--xt-accent); margin-bottom: 8px; letter-spacing: 1px; } .xt-text-theLie::before { content: "谎言 / "; color: var(--xt-accent); font-weight: bold; } .xt-text-impulse::before { content: "冲动 / "; color: var(--xt-accent); font-weight: bold; }

.xt-root > .xt-content > .xt-card:nth-of-type(1) { display: block; background: transparent; border: none; padding: 0; position: relative; z-index: 1; } .xt-root > .xt-content > .xt-card:nth-of-type(2) { display: none; background: transparent; border: none; padding: 0; position: relative; z-index: 1; }
.xt-action-1 { display: block; text-align: center; padding: 10px; margin: 20px 0 10px 0; color: var(--xt-accent); cursor: pointer; letter-spacing: 4px; font-size: 11px; border: 1px dashed var(--xt-border); border-radius: 4px; transition: all 0.4s ease; } .xt-action-1::after { content: "「 翻阅深夜的信笺 ▽ 」"; } .xt-action-1:hover { letter-spacing: 8px; background: var(--xt-accent-bg); } #xt-t1:checked ~ .xt-content .xt-action-1::after { content: "「 合上信笺 △ 」"; } #xt-t1:checked ~ .xt-content > .xt-card:nth-of-type(1) { display: none; } #xt-t1:checked ~ .xt-content > .xt-card:nth-of-type(2) { display: block; animation: xt-fadeInUp 0.8s ease forwards; }

/* 图像染成暗紫色调 */
.xt-root > .xt-content > .xt-card:nth-of-type(1)::before { content: ""; position: absolute; top: -15px; right: -15px; width: 170px; height: 170px; background: url('https://img.heliar.top/file/1776773692933_1776773637750.png') no-repeat center/cover; opacity: 0.5; mask-image: radial-gradient(circle at top right, black 30%, transparent 70%); -webkit-mask-image: radial-gradient(circle at top right, black 30%, transparent 70%); pointer-events: none; z-index: -1; filter: sepia(40%) hue-rotate(250deg); }
.xt-root > .xt-content > .xt-card:nth-of-type(2)::before { content: ""; position: absolute; bottom: -15px; left: -15px; width: 200px; height: 200px; background: url('https://img.heliar.top/file/1776773694238_1776773621767.png') no-repeat center/cover; opacity: 0.4; mask-image: radial-gradient(circle at bottom left, black 30%, transparent 70%); -webkit-mask-image: radial-gradient(circle at bottom left, black 30%, transparent 70%); pointer-events: none; z-index: -1; filter: sepia(40%) hue-rotate(250deg); }

.xt-row { display: flex !important; align-items: flex-start; gap: 12px; } .xt-row > .xt-card { flex: 1; min-width: 0; background: rgba(13, 8, 13, 0.85); backdrop-filter: blur(4px); border: 1px solid var(--xt-border); transition: transform 0.4s, box-shadow 0.4s; padding: 12px; margin-bottom: 0 !important; } .xt-row > .xt-card:nth-child(1) { transform: rotate(-2deg); box-shadow: 5px 5px 15px rgba(0,0,0,0.8); } .xt-row > .xt-card:nth-child(2) { transform: rotate(3deg); box-shadow: -5px 5px 15px rgba(0,0,0,0.6); } .xt-row > .xt-card:hover { transform: rotate(0deg) translateY(-2px); z-index: 10; box-shadow: 0 10px 25px rgba(0,0,0,0.9); border-color: var(--xt-accent); }

.xt-section-私人运势 .xt-section-body { font-style: italic; color: #a394a3; line-height: 1.6; font-size: 11px; }

.xt-text-deletedText { position: relative; margin: 15px 0 25px 0; padding: 12px 15px; background: rgba(255, 255, 255, 0.02); border: 1px solid var(--xt-border); border-radius: 8px; color: var(--xt-text); font-size: 13px; text-align: left; transition: all 0.5s ease; cursor: crosshair; } .xt-text-deletedText::before { content: "草稿箱"; position: absolute; top: -8px; left: 12px; background: var(--xt-bg); color: var(--xt-text-muted); font-size: 10px; padding: 0 5px; } .xt-text-deletedText::after { content: "|"; color: var(--xt-text-sub); animation: blink 1s step-end infinite; margin-left: 2px; } @keyframes blink { 50% { opacity: 0; } } .xt-text-deletedText:hover { color: var(--xt-text-muted); border-color: var(--xt-accent); text-decoration: line-through; text-decoration-color: var(--xt-accent); text-decoration-thickness: 2px; } .xt-text-deletedText:hover::after { display: none; } .xt-text-deletedText:hover::before { content: "已删除"; color: var(--xt-accent); }

.xt-section-深夜强迫症行为 { background: rgba(13, 8, 13, 0.6); border: 1px solid var(--xt-border); padding: 12px; margin: 15px 0; border-radius: 4px; } .xt-section-深夜强迫症行为 .xt-section-body { display: flex; gap: 10px; flex-wrap: wrap; } .xt-section-深夜强迫症行为 .xt-list-item { flex: 1; min-width: 120px; background: var(--xt-accent-bg); border-left: 2px solid var(--xt-border); padding: 8px 8px 8px 24px; font-size: 11px; color: var(--xt-text-sub); margin-bottom: 0; position: relative; cursor: pointer; transition: all 0.3s; } .xt-section-深夜强迫症行为 .xt-list-check { display: none; } .xt-section-深夜强迫症行为 .xt-list-text { position: relative; display: inline-block; transition: color 0.3s; } .xt-section-深夜强迫症行为 .xt-list-item::before { content: ""; position: absolute; left: 6px; top: 50%; transform: translateY(-50%); width: 10px; height: 10px; border: 1px solid var(--xt-text-muted); border-radius: 2px; transition: all 0.3s; } .xt-section-深夜强迫症行为 .xt-list-item::after { content: "✓"; position: absolute; left: 8px; top: 50%; transform: translateY(-50%) scale(0); color: var(--xt-accent); font-size: 12px; font-weight: bold; opacity: 0; transition: all 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275); } .xt-section-深夜强迫症行为 .xt-list-text::after { content: ""; position: absolute; left: 0; top: 50%; height: 1px; background: var(--xt-accent); width: 0; transition: width 0.4s ease; } .xt-section-深夜强迫症行为 .xt-list-item:hover { border-left-color: var(--xt-accent); } .xt-section-深夜强迫症行为 .xt-list-item:hover::before { border-color: var(--xt-accent); } .xt-section-深夜强迫症行为 .xt-list-item:hover::after { transform: translateY(-50%) scale(1); opacity: 1; } .xt-section-深夜强迫症行为 .xt-list-item:hover .xt-list-text { color: var(--xt-text-muted); } .xt-section-深夜强迫症行为 .xt-list-item:hover .xt-list-text::after { width: 100%; }

.xt-section-旁观者言 { margin-top: 25px; padding-top: 15px; border-top: 1px dashed var(--xt-border); } .xt-section-旁观者言 .xt-list-item { font-size: 11px; color: var(--xt-text-sub); border-left: 2px solid var(--xt-border); padding-left: 10px; margin-bottom: 15px; line-height: 1.8; } .xt-section-旁观者言 .xt-list-item::first-line { color: #e6dce6; }
.xt-text-bookQuote { text-align: center; font-size: 14px; color: #ffffff; margin: 25px 0 5px 0; letter-spacing: 2px; } .xt-text-bookQuote::before { content: "「 "; color: var(--xt-accent); font-weight: bold; } .xt-text-bookQuote::after { content: " 」"; color: var(--xt-accent); font-weight: bold; } .xt-text-bookAnnotation { text-align: right; font-size: 11px; color: var(--xt-text-sub); font-style: italic; margin-bottom: 30px; padding-right: 15px; } .xt-text-bookAnnotation::before { content: "批注："; color: var(--xt-accent); font-style: normal; font-weight: bold; }

.xt-marquee { background: var(--xt-accent); color: #000; font-weight: bold; letter-spacing: 5px; padding: 5px 0; transform: rotate(-2deg); margin: 20px -20px; box-shadow: 0 5px 15px rgba(133, 92, 133, 0.4); border-top: 1px solid #b88eb8; border-bottom: 1px solid #b88eb8; }
.xt-section-私人账单流水 .xt-list-item { font-family: monospace; font-size: 10px; color: var(--xt-text-sub); border-bottom: 1px dashed var(--xt-text-muted); padding: 6px 0; transition: color 0.3s; cursor: pointer; } .xt-section-私人账单流水 .xt-list-item:last-child { border-bottom: none; } .xt-section-私人账单流水 .xt-list-item:hover { color: #fff; text-shadow: 0 0 5px rgba(255,255,255,0.3); }
.xt-section-隐秘搜寻 .xt-list-item { font-family: monospace; font-size: 11px; margin-bottom: 6px; color: #000; background: #000; border: 1px solid var(--xt-border); padding: 4px 6px; border-radius: 2px; transition: all 0.4s; cursor: pointer; } .xt-section-隐秘搜寻 .xt-list-item:hover { background: transparent; border-color: transparent; color: var(--xt-accent); }
.xt-section-脑内幻想 .xt-section-body { font-style: italic; color: #bbaabb; font-size: 12px; }
.xt-section-平行时空残页 { margin-top: 20px; } .xt-section-平行时空残页 .xt-section-body { border-left: 2px solid var(--xt-accent); padding-left: 15px; background: linear-gradient(90deg, var(--xt-accent-bg), transparent); font-size: 12px; }
.xt-text-postscript { text-align: right; font-size: 12px; color: var(--xt-text); margin-top: 25px; letter-spacing: 1px; }

value.layout:
# --- 第一页：白昼的克制 ---
@card
@text timestamp .fadeInDown
@header charImage charName .fadeInDown

@quote innerVoice .fadeInUp

@text theLie .fadeInUp.delay100
@text impulse .fadeInUp.delay100

# 修复：状态和好感度彻底分开，保证圆环完美显示！
@grid 1
status:stat "STATUS"
@ring resonance "RESONANCE"

# 弹性双列：左边运势，右边BGM
@row 2
@card
@section ✦ 情绪感知
colorPalette
fragranceNote
@section ✦ 私人运势
fortune
@endcard

@card
@section ✦ 正在播放
bgm
@section ✦ 私人账单流水
@list
bill1
bill2
bill3
@endcard
@endrow
@endcard

# --- 翻页交互按钮 ---
@toggle 1

# --- 第二页：深夜的失控 ---
@card
@text deletedText

@if resonance > 85
@marquee obsession .shimmer
@endif

# 全宽横向大卡片：待办事项
@section ❖ 深夜强迫症行为
@list
todo1
todo2

# 弹性双列：搜索与幻想
@row 2
@card
@section ❖ 隐秘搜寻
@list
search1
search2
@endcard

@card
@section ❖ 脑内幻想
fantasy
@endcard
@endrow

@divider

# 名言与私人批注
@text bookQuote .float
@text bookAnnotation .float

# 旁观者言
@section ❖ 旁观者言
@list
review1
review2
review3

@section ⚝ 平行时空残页
theater
@text postscript
@endcard
